import { IconRefresh } from '@arco-design/iconbox-react-ve-o-design';
import { Button, CAsyncContent, Space } from '@cloud-materials/common';
import dayjs from 'dayjs';
import React, { useRef } from 'react';
import type { CAsyncContentRef } from '../interface';

export default () => {
  const ref = useRef<CAsyncContentRef>(null);
  return (
    <>
      <CAsyncContent
        fetcher={() =>
          new Promise<number>(resolve => {
            setTimeout(() => {
              resolve(Date.now());
            }, 1e3);
          })
        }
      >
        {(v, { refresh, loading }) => (
          <div style={{ textAlign: 'center', padding: 20 }}>
            <Space>
              <span>现在时间是：{dayjs(v).format('YYYY-MM-DD HH:mm:ss')}</span>
              <Button icon={<IconRefresh />} size="mini" onClick={() => refresh()} loading={loading} />
            </Space>
          </div>
        )}
      </CAsyncContent>
      <CAsyncContent
        fetcher={() =>
          new Promise<number>((_, reject) => {
            setTimeout(() => {
              reject(new Error());
            }, 1e3);
          })
        }
      >
        {() => null}
      </CAsyncContent>
      <CAsyncContent
        ref={ref}
        fetcher={() =>
          new Promise<number>((_, reject) => {
            setTimeout(() => {
              reject(new Error());
            }, 1e3);
          })
        }
        cLoadingProps={{
          cResultProps: {
            title: (
              <>
                <p>:-( 通过透传 loadingProps 自定义文案，更多参数请参考 CLoadingV2</p>
                <Button
                  onClick={() => {
                    ref.current?.refresh();
                  }}
                >
                  重试
                </Button>
              </>
            ),
          },
        }}
      >
        {() => null}
      </CAsyncContent>
    </>
  );
};

import { IconRefresh } from '@arco-design/iconbox-react-ve-o-design';
import { Button, CAsyncContent, Skeleton } from '@cloud-materials/common';
import dayjs from 'dayjs';
import React, { useState } from 'react';
import { faker } from '@faker-js/faker';

export default () => {
  const [load, setLoad] = useState(0);
  return (
    <>
      <Button
        onClick={() => {
          setLoad(Date.now());
        }}
      >
        开始加载
      </Button>
      <br />
      <br />
      {load > 0 && (
        <CAsyncContent
          key={load}
          fetcher={() => {
            const data = {
              time: Date.now(),
              title: faker.lorem.words(3),
              content: faker.lorem.words(100),
              author: faker.person.fullName(),
            };

            return new Promise<typeof data>(resolve => {
              setTimeout(() => {
                resolve(data);
              }, 2e3);
            });
          }}
          placeholder={<Skeleton animation text={{ rows: 7 }} />}
        >
          {(v, { refresh, loading }) => (
            <>
              <span>现在时间是：{dayjs(v.time).format('YYYY-MM-DD HH:mm:ss')} </span>
              <Button icon={<IconRefresh />} size="mini" onClick={() => refresh()} loading={loading} />
              <p>
                <strong>{v.title}</strong>
              </p>
              <p>Author：{v.author}</p>
              <p>{v.content}</p>
            </>
          )}
        </CAsyncContent>
      )}
    </>
  );
};

import { IconRefresh } from '@arco-design/iconbox-react-ve-o-design';
import { Button, CAsyncContent, CModal, Space } from '@cloud-materials/common';
import dayjs from 'dayjs';
import React, { useState } from 'react';
import DemoContainerJustForDemo from '../../CModal/__docs__/DemoContainerJustForDemo';

export default () => {
  const [id] = useState(() => Math.random().toString());
  return (
    <>
      <Button
        onClick={() => {
          CModal.open({
            title: '在CModal中使用',
            content: (
              <CAsyncContent
                fetcher={() =>
                  new Promise<number>(resolve => {
                    setTimeout(() => {
                      resolve(Date.now());
                    }, 1e3);
                  })
                }
              >
                {(v, { refresh, loading }) => (
                  <div style={{ textAlign: 'center', padding: 20 }}>
                    <Space>
                      <span>现在时间是：{dayjs(v).format('YYYY-MM-DD HH:mm:ss')}</span>
                      <Button icon={<IconRefresh />} size="mini" onClick={() => refresh()} loading={loading} />
                    </Space>
                  </div>
                )}
              </CAsyncContent>
            ),
            // 以下仅为demo演示必须要的内容
            wrapper: [DemoContainerJustForDemo],
            getMountContainer: () => document.getElementById(id)!,
          });
        }}
      >
        在CModal中使用
      </Button>
      <div id={id} />
    </>
  );
};
